use super::{assert_close, check_fixed, check_fixed_rescale, F32_TOL, F64_TOL, ROUND_TRIP_TOL};
use qty::*;

#[test]
fn bytes() {
    for v in [1.0, 0.3, -42.75, 1e6, 123456.789] {
        // Generated conversion vs. the upstream formula, verbatim.
        let x: f64 = v;
        let base = x * 8.0;
        assert_close(Information::from_bytes(v).as_base(), base, F64_TOL);
        let x: f64 = base;
        let back = x / 8.0;
        assert_close(Information::from_base(base).as_bytes(), back, F64_TOL);
        assert_close(Information::from_bytes(v).as_bytes(), v, ROUND_TRIP_TOL);
        // f32 storage.
        assert_close(
            Information::from_bytes(v as f32).as_base() as f64,
            base,
            F32_TOL,
        );
        assert_close(
            Information::from_base(base as f32).as_bytes() as f64,
            back,
            F32_TOL,
        );
    }
}

